-- ============================================================
-- 小区管理升级：接入《1_3_1_寺家庄镇-小区台账》（数据源：金山文档）
-- 共 26 条台账记录
-- ============================================================

-- 1) 新增字段
ALTER TABLE `community`
  ADD COLUMN `legal_person` varchar(50)  DEFAULT NULL COMMENT '法人代表',
  ADD COLUMN `company_phone` varchar(50)  DEFAULT NULL COMMENT '企业联系电话',
  ADD COLUMN `community_org` varchar(120) DEFAULT NULL COMMENT '所属乡镇（区）、社区居委会',
  ADD COLUMN `build_time` varchar(50)  DEFAULT NULL COMMENT '建设时间',
  ADD COLUMN `property_type` varchar(30)  DEFAULT NULL COMMENT '物业性质',
  ADD COLUMN `area_residential` decimal(10,4) DEFAULT NULL COMMENT '建筑面积-住宅(万㎡)',
  ADD COLUMN `area_commercial` decimal(10,4) DEFAULT NULL COMMENT '建筑面积-商业(万㎡)',
  ADD COLUMN `building_multi` varchar(120) DEFAULT NULL COMMENT '多层楼栋数/层数',
  ADD COLUMN `building_high` varchar(120) DEFAULT NULL COMMENT '高层楼栋数/层数',
  ADD COLUMN `households_residential` int         DEFAULT NULL COMMENT '住宅户数',
  ADD COLUMN `households_commercial` int          DEFAULT NULL COMMENT '商业户数',
  ADD COLUMN `parking_ground` int          DEFAULT NULL COMMENT '机动车位-地上(个)',
  ADD COLUMN `parking_underground` int          DEFAULT NULL COMMENT '机动车位-地下(个)',
  ADD COLUMN `charging_ground` int          DEFAULT NULL COMMENT '机动车充电桩-地上(个)',
  ADD COLUMN `charging_underground` int          DEFAULT NULL COMMENT '机动车充电桩-地下(个)',
  ADD COLUMN `nonmotor_ground` int          DEFAULT NULL COMMENT '非机动车位-地上(个)',
  ADD COLUMN `nonmotor_underground` int          DEFAULT NULL COMMENT '非机动车位-地下(个)',
  ADD COLUMN `ebike_shed` varchar(20)  DEFAULT NULL COMMENT '电动车充电设备-车棚',
  ADD COLUMN `ebike_port` int          DEFAULT NULL COMMENT '电动车充电设备-充电头(个)',
  ADD COLUMN `elevator_count` int          DEFAULT NULL COMMENT '电梯(部)',
  ADD COLUMN `fire_station` int          DEFAULT NULL COMMENT '微型消防站(个)',
  ADD COLUMN `smoke_detector` int          DEFAULT NULL COMMENT '独立烟感(个)',
  ADD COLUMN `fire_hydrant` int          DEFAULT NULL COMMENT '消火栓(个)',
  ADD COLUMN `water_managed` varchar(10)  DEFAULT NULL COMMENT '水是否一管到户',
  ADD COLUMN `power_managed` varchar(10)  DEFAULT NULL COMMENT '电是否一管到户',
  ADD COLUMN `heat_managed` varchar(10)  DEFAULT NULL COMMENT '暖是否一管到户',
  ADD COLUMN `takeover_mode` varchar(30)  DEFAULT NULL COMMENT '承接方式',
  ADD COLUMN `ledger_remark` varchar(255) DEFAULT NULL COMMENT '台账备注（未交房注明）';

